    cb.append(next_bd(today, include=False))
    vars['callback_days_text'] = ' or '.join(say(d) + ' (' + d2s(d) + ')' for d in cb)
    vars['callback_days_iso'] = ','.join(d2s(d) for d in cb)
    lines = []
