def band_for(value):
    for b in P['bands']:
        try:
            v = float(value)
            if (b.get('min') is None or v >= float(b['min'])) and (b.get('max') is None or v <= float(b['max'])): return b
        except Exception: pass
    return None

def derived(today, deadline, product):
    # attempt 1: the last business day of this week; if today is that day (or it has already passed), the last business day of next week
    a1 = last_bd_of_week(today)
    if a1 is None or a1 <= today:
        a1 = last_bd_of_week(today + datetime.timedelta(days=7))
    if a1 is None:
        a1 = next_bd(today, include=False)
    if a1 > deadline:
        a1 = deadline
    # attempt 2: the deadline (late band only)
    a2 = deadline
    # vague period: propose the deadline
    vague = deadline
    # replacement for a non-business day: the next business day after it (default reference: today)
    repl = next_bd(today, include=False)
    return {
        "attempt1_date": a1,
        "attempt2_date": a2,
        "deadline": deadline,
        "vague_period_default": vague,
        "non_business_day_replacement": repl,
    }


def parse_products():
    prods = vars.get('products')
    if isinstance(prods, str):
        t = prods.strip()
        try: prods = json.loads(t)
        except Exception:
            try: prods = json.loads(t.replace("'", '"').replace('True', 'true').replace('False', 'false').replace('None', 'null'))
            except Exception: prods = None
    if isinstance(prods, dict): prods = [prods]
    if not isinstance(prods, list) or not prods:
